    /**
     * Method to retrieve the Gateway via an GatewayPrimaryKey.
     * @param 	id Long
     * @return 	Gateway
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Gateway handle( FindGatewayQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getGatewayId() );
    }
    
    /**
     * Method to retrieve a collection of all Gateways
     *
     * @param	query	FindAllGatewayQuery 
     * @return 	List<Gateway> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Gateway> handle( FindAllGatewayQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindGateway,
 * but only if the id matches
 *
 * @param		entity	Gateway
 */
	protected void emitFindGateway( Gateway entity ) {
		LOGGER.info("handling emitFindGateway" );
		
	    queryUpdateEmitter.emit(FindGatewayQuery.class,
	                            query -> query.getFilter().getGatewayId().equals(entity.getGatewayId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllGateway
	 * 
	 * @param		entity	Gateway
	 */
	protected void emitFindAllGateway( Gateway entity ) {
		LOGGER.info("handling emitFindAllGateway" );
		
	    queryUpdateEmitter.emit(FindAllGatewayQuery.class,
	                            query -> true,
	                            entity);
	}

